    39	export function resolvePersonaShape(identity: string, explicitShape?: string | null): string {
    40	  if (explicitShape) {
    41	    const explicit = GROK_SHAPES[explicitShape];
    42	    if (explicit) return explicit;
    43	  }
    44	  let hash = shippedHash(identity);
    45	  hash = Math.imul(hash ^ (hash >>> 16), 73244475);
    46	  hash = Math.imul(hash ^ (hash >>> 13), 3266489909);
    47	  const shapeIndex = ((hash ^ (hash >>> 16)) >>> 0) % SHIPPED_SHAPE_KEYS.length;
    48	  const key = SHIPPED_SHAPE_KEYS[shapeIndex] ?? "hex";
    49	  return GROK_SHAPES[key] ?? FALLBACK_SHAPE_PATH;
    50	}
