   271	const VISOR_BORDER_PX = 1;
   272	
   273	function robotFaceLayout(size: number) {
   274	  const visorW = Math.round(size * 0.68);
   275	  const visorH = Math.round(size * 0.44);
   276	  const visorInnerW = Math.max(0, visorW - VISOR_BORDER_PX * 2);
   277	  const visorInnerH = Math.max(0, visorH - VISOR_BORDER_PX * 2);
   278	  const preferredEyeW = Math.max(4, Math.round(size * 0.14));
   279	  const preferredEyeH = Math.max(7, Math.round(size * 0.22));
   280	  const preferredEyeGap = Math.max(3, Math.round(size * 0.1));
   281	  const preferredSpan = preferredEyeW * 2 + preferredEyeGap;
   282	  const scale = Math.min(1, visorInnerW / preferredSpan, visorInnerH / preferredEyeH);
   283	  const eyeW = Math.floor(preferredEyeW * scale);
   284	  const eyeH = Math.floor(preferredEyeH * scale);
   285	  const eyeGap = Math.floor(preferredEyeGap * scale);
   286	  const eyeRadius = Math.max(2, Math.round(eyeW * 0.5));
   287	  return { visorW, visorH, eyeW, eyeH, eyeGap, eyeRadius };
   288	}
   289	
   290	function RobotAvatar({
   291	  colorDef,
   292	  size,
   293	  isWorking,
   294	  className,
   295	  identity,
   296	  gradientId,
   297	}: {
   298	  colorDef: GrokColorDef;
   299	  size: number;
   300	  isWorking: boolean;
   301	  className?: string;
   302	  identity: string;
   303	  gradientId: string;
   304	}) {
   305	  const seed = avatarIdentitySeed(identity || colorDef.hex);
   306	  const eyeVariant = seed % 4;
   307	  const idleDuration = (4.2 + ((seed * 7) % 28) / 10).toFixed(2);
   308	  const idleDelay = (-(((seed * 13) % 45) / 10)).toFixed(2);
   309	  const { visorW, visorH, eyeW, eyeH, eyeGap, eyeRadius } = robotFaceLayout(size);
   310	  const eyeGlow = `0 0 4px #fff, 0 0 8px #fff, 0 0 14px ${colorDef.light}`;
   311	  const idleEyeAnimation = {
   312	    "--rakazo-eye-animation-name": `rakazo-eyes-idle-${eyeVariant}`,
   313	    "--rakazo-eye-animation-duration": `${idleDuration}s`,
   314	    "--rakazo-eye-animation-easing": "cubic-bezier(0.4, 0, 0.2, 1)",
