 96	export function useAgents(): AgentSummary[] {
 97	  const [agents, setAgents] = useState(FALLBACK_AGENTS);
 98	  useEffect(() => {
 99	    const abort = new AbortController();
100	    fetch("/api/agents", { signal: abort.signal })
101	      .then((res) => {
102	        if (res.status === 401) {
103	          handleUnauthorized();
104	          return null;
105	        }
106	        return res.ok ? res.json() : null;
107	      })
108	      .then((list: unknown) => {
109	        if (isAgentList(list) && list.length > 0) setAgents(list);
110	      })
111	      .catch(() => undefined);
112	    return () => abort.abort();
113	  }, []);
