  1	import { createAuthClient } from "better-auth/react";
  2	import { adminClient, usernameClient } from "better-auth/client/plugins";
  3	
  4	/**
  5	 * Better Auth client. The API is served from the same origin, so no baseURL: the client falls
  6	 * back to the relative `/api/auth`. Mirrors the server plugins (username sign-in, admin roles).
  7	 */
  8	
  9	export type Role = "admin" | "employee";
 10	
 11	export const authClient = createAuthClient({
 12	  plugins: [usernameClient(), adminClient()],
 13	});
 14	
 15	export const { useSession, signOut } = authClient;
 16	
 17	export async function signInWithUsername(username: string, password: string) {
 18	  const result = await authClient.signIn.username({ username, password });
 19	  if (!result.error) unauthorizedHandled = false;
 20	  return result;
 21	}
 22	
 23	/** One 401 round per session: repeated notifications would keep cancelling the session re-check. */
 24	let unauthorizedHandled = false;
 25	
 26	/** The server stores any string; only these two roles are known to the UI. */
 27	export function toRole(role: string | null | undefined): Role {
 28	  return role === "admin" ? "admin" : "employee";
 29	}
 30	
 31	/** Per-user client state (e.g. in-memory chats) registers here to be wiped when the session ends. */
 32	const sessionResetters = new Set<() => void>();
 33	
 34	export function onSessionReset(reset: () => void) {
 35	  sessionResetters.add(reset);
 36	}
 37	
 38	export function clearSessionState() {
 39	  for (const reset of sessionResetters) reset();
 40	}
 41	
 42	/**
 43	 * The server rejected our cookie (401). Drop per-user state and nudge the session store to
 44	 * re-check: get-session then returns null, so the App gate falls back to the login page. The
 45	 * login page makes no requests of its own, so a dead cookie cannot loop.
 46	 */
 47	export function handleUnauthorized() {
 48	  if (unauthorizedHandled) return;
 49	  unauthorizedHandled = true;
 50	  clearSessionState();
 51	  authClient.$store.notify("$sessionSignal");
 52	}

