 12	/** How long pointer moves are ignored after a snap, so the spring isn't cut short. */
 13	const SNAP_SETTLE_MS = 180;
 14	/** If no shared avatar starts travelling after a flip, start the width anyway. */
 15	const TRAVEL_FALLBACK_MS = 50;
 16	
 17	export function Sidebar({ docked, ...props }: SidebarPanelProps & { docked: boolean }) {
 18	  return docked ? <DockedSidebar {...props} /> : <OverlaySidebar {...props} />;
 19	}
