 21	/** Mobile: slides in from the start edge (App mounts it under AnimatePresence). */
 22	function OverlaySidebar(props: SidebarPanelProps) {
 23	  return (
 24	    <m.aside
 25	      data-testid="sidebar"
 26	      data-layout="overlay"
 27	      variants={sidebarMobile}
 28	      initial="hidden"
