 30	      exit="hidden"
 31	      className="absolute inset-y-0 start-0 z-40 flex w-[calc(100%-48px)] max-w-[284px] flex-col border-e border-sidebar-border bg-sidebar"
 32	    >
 33	      <ExpandedPanel {...props} />
