 38	/**
 39	 * Desktop: always docked. Width is a motion value so dragging follows the pointer 1:1 with
 40	 * no animation. Switching layouts is a three-phase morph (see SidebarMorphContext): labels
 41	 * fade out, then the layouts flip while the shared avatars and the width travel together
 42	 * (one uniform ease-in-out tween, the same for opening, closing and drag snaps), then labels
 43	 * fade in. Collapse plays the same sequence backwards.
 44	 */
 45	function DockedSidebar(props: SidebarPanelProps) {
 46	  const reduce = useReducedMotion();
 47	  const [compact, setCompact] = useState(readSidebarCompact);
 48	  const [width, setWidth] = useState(readSidebarWidth);
 49	  const [dragging, setDragging] = useState(false);
 50	  const [chrome, setChromeState] = useState(true);
 51	  const [travel, setTravel] = useState<Transition | undefined>(undefined);
 52	  /** Layout currently rendered. */
 53	  const compactRef = useRef(compact);
 54	  /** Layout being moved to (differs from compactRef while phase 1 is pending). */
 55	  const targetRef = useRef(compact);
 56	  const chromeRef = useRef(true);
 57	  const widthRef = useRef(width);
 58	  const size = useMotionValue(compact ? SIDEBAR.RAIL : width);
 59	  // The expanded panel's own width, pinned to its target (not derived from `size`), so its
 60	  // layout — the centered tile, row widths — doesn't drift while the aside animates.
 61	  const panelWidth = useMotionValue(width);
 62	  // origin: the expanded width when the drag began — what a snap back to expanded restores.
 63	  const drag = useRef<{ startX: number; base: number; origin: number } | null>(null);
 64	  const settleUntil = useRef(0);
 65	  /** Increments per setMode; stale timers/animation callbacks compare against it. */
 66	  const runRef = useRef(0);
 67	  const cancelFlip = useRef<(() => void) | null>(null);
 68	  const pendingTravel = useRef<{ run: number; target: number; transition: Transition } | null>(null);
 69	  const [flipCount, setFlipCount] = useState(0);
 70	
 71	  const setChrome = (value: boolean) => {
 72	    chromeRef.current = value;
 73	    setChromeState(value);
 74	  };
 75	
 76	  const commit = (nextWidth: number, nextCompact: boolean) => {
 77	    widthRef.current = nextWidth;
 78	    compactRef.current = nextCompact;
 79	    setWidth(nextWidth);
 80	    setCompact(nextCompact);
 81	    writeSidebarLayout(nextWidth, nextCompact);
 82	  };
 83	
 84	  const setMode = (nextCompact: boolean, how: "toggle" | "snap") => {
 85	    if (nextCompact === targetRef.current) return;
 86	    targetRef.current = nextCompact;
 87	    const run = ++runRef.current;
 88	    cancelFlip.current?.();
 89	    cancelFlip.current = null;
 90	
 91	    // Reversed during phase 1: the layouts never flipped, so just bring the labels back.
 92	    if (nextCompact === compactRef.current) {
 93	      setChrome(true);
 94	      return;
 95	    }
 96	
 97	    const target = nextCompact ? SIDEBAR.RAIL : widthRef.current;
 98	    if (reduce) {
 99	      size.jump(target);
100	      if (!nextCompact) panelWidth.jump(widthRef.current);
101	      commit(widthRef.current, nextCompact);
102	      setChrome(true);
103	      return;
104	    }
105	
106	    const transition = SIDEBAR_SLIDE;
107	    // Phase 2: flip the layouts; shared avatars travel with the width. The width animation
108	    // itself starts in the flip's layout effect (below), i.e. after React commits the new
109	    // layout — the same frame the avatars' layout animations start — so both land together.
110	    const flip = () => {
111	      if (run !== runRef.current) return;
112	      cancelFlip.current = null;
113	      // A reversal mid-travel: hold the width where it is until the new travel starts with
114	      // the shared elements, instead of letting the old tween run on for a frame.
115	      size.stop();
116	      settleUntil.current = performance.now() + SNAP_SETTLE_MS;
117	      if (!nextCompact) panelWidth.jump(widthRef.current);
118	      pendingTravel.current = { run, target, transition };
119	      setTravel(transition);
120	      setFlipCount((count) => count + 1);
121	      commit(widthRef.current, nextCompact);
122	    };
123	
124	    // Phase 1: labels fade out first (skipped if they're already hidden mid-morph).
125	    if (chromeRef.current) {
126	      setChrome(false);
127	      cancelFlip.current = delay(flip, DURATION.base * 1000);
128	    } else {
129	      flip();
130	    }
131	  };
132	  const toggle = () => setMode(!targetRef.current, "toggle");
133	  /** Phase 1 in progress: the layouts are about to flip. */
134	  const flipPending = () => cancelFlip.current !== null;
135	
136	  /**
137	   * Phase 2's width animation starts together with the shared avatars' layout animations
138	   * (their onLayoutAnimationStart), so width and avatars run on one clock and land on the
139	   * same frame. Depending on the layout being mounted, Motion starts those a frame after
140	   * the commit, so starting the width at commit time would let it lead by a frame.
141	   */
142	  const startTravel = () => {
143	    const pending = pendingTravel.current;
144	    if (!pending) return;
145	    pendingTravel.current = null;
146	    // onStop as well as onComplete: a stopped animation never resolves (a drag jump or a
147	    // newer run stops it); the run id ignores stale ones.
148	    const landed = () => {
149	      if (pending.run === runRef.current) setChrome(true);
150	    };
151	    animate(size, pending.target, { ...pending.transition, onComplete: landed, onStop: landed });
152	  };
153	  // Fallback when no avatar travels (e.g. no agents): start shortly after the flip commits.
154	  useLayoutEffect(() => {
155	    if (!pendingTravel.current) return;
156	    return delay(startTravel, TRAVEL_FALLBACK_MS);
157	  }, [flipCount]);
158	
159	  // No text selection and a resize cursor everywhere while dragging.
160	  useEffect(() => {
161	    if (!dragging) return;
162	    const { style } = document.body;
163	    const previous = { userSelect: style.userSelect, cursor: style.cursor };
164	    style.userSelect = "none";
165	    style.cursor = "col-resize";
166	    return () => {
167	      style.userSelect = previous.userSelect;
168	      style.cursor = previous.cursor;
169	    };
170	  }, [dragging]);
171	
172	  const onPointerDown = (event: PointerEvent<HTMLDivElement>) => {
173	    if (event.button !== 0) return;
174	    event.preventDefault();
175	    event.currentTarget.setPointerCapture(event.pointerId);
176	    drag.current = {
177	      startX: event.clientX,
178	      base: compactRef.current ? SIDEBAR.RAIL : size.get(),
179	      origin: widthRef.current,
180	    };
181	    setDragging(true);
182	  };
183	
184	  const onPointerMove = (event: PointerEvent<HTMLDivElement>) => {
185	    const current = drag.current;
186	    // Ignore moves while a snap is fading its labels out (phase 1) or its spring is settling.
187	    if (!current || flipPending() || performance.now() < settleUntil.current) return;
188	    const candidate = current.base + (event.clientX - current.startX);
189	    if (compactRef.current) {
190	      if (candidate > SIDEBAR.SNAP_TO_EXPANDED) {
191	        setMode(false, "snap");
192	        drag.current = { ...current, startX: event.clientX, base: widthRef.current };
193	      }
194	      return;
195	    }
196	    if (candidate < SIDEBAR.SNAP_TO_RAIL) {
197	      // The edge passed through MIN on the way here; remember the width the drag started at.
198	      widthRef.current = current.origin;
199	      setMode(true, "snap");
200	      drag.current = { ...current, startX: event.clientX, base: SIDEBAR.RAIL };
201	      return;
202	    }
203	    // Between MIN and the snap threshold the edge holds at MIN (a little resistance).
204	    const next = clampWidth(candidate);
205	    size.jump(next);
206	    panelWidth.jump(next);
207	    widthRef.current = next;
208	  };
209	
210	  const endDrag = () => {
211	    if (!drag.current) return;
212	    drag.current = null;
213	    setDragging(false);
214	    commit(widthRef.current, compactRef.current);
215	  };
216	
217	  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
218	    if (event.key === "Enter" || event.key === " ") {
219	      event.preventDefault();
220	      toggle();
221	      return;
222	    }
223	    if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
224	    event.preventDefault();
225	    // Arrow resizing waits for an in-flight morph (Enter can still reverse it).
226	    if (flipPending() || !chromeRef.current) return;
227	    const step = event.shiftKey ? SIDEBAR.STEP_LARGE : SIDEBAR.STEP;
228	    const grow = event.key === "ArrowRight";
229	    if (compactRef.current) {
230	      if (grow) setMode(false, "toggle");
231	      return;
232	    }
233	    if (!grow && widthRef.current <= SIDEBAR.MIN) {
234	      setMode(true, "toggle");
235	      return;
236	    }
237	    const next = clampWidth(widthRef.current + (grow ? step : -step));
238	    size.jump(next);
239	    panelWidth.jump(next);
240	    commit(next, false);
241	  };
242	
243	  const panelProps = { ...props, onToggleCompact: toggle };
244	
245	  return (
246	    <m.aside
247	      data-testid="sidebar"
248	      data-layout={compact ? "rail" : "expanded"}
249	      data-morph={chrome ? "idle" : "morphing"}
250	      data-dragging={dragging || undefined}
251	      style={{ width: size }}
252	      className="relative h-full shrink-0 border-e border-sidebar-border bg-sidebar"
253	    >
254	      <SidebarMorphContext.Provider value={{ chrome, travel, onTravelStart: startTravel }}>
255	        {/* No AnimatePresence: by the flip the old layout holds only faded labels and the
256	            shared avatars, which hand off to the new layout's copies (layoutId). */}
257	        <div className="absolute inset-0 overflow-hidden">
258	          {compact ? (
259	            <div key="rail" className="absolute inset-0">
260	              <RailPanel {...panelProps} />
261	            </div>
262	          ) : (
263	            <m.div key="expanded" className="absolute inset-y-0 start-0" style={{ width: panelWidth }}>
264	              <ExpandedPanel {...panelProps} />
265	            </m.div>
266	          )}
267	        </div>
268	      </SidebarMorphContext.Provider>
269	      {/* Resize handle on the end edge: drag, double-click, or keyboard (arrows resize, Enter toggles). */}
270	      <div
271	        role="separator"
272	        tabIndex={0}
273	        aria-orientation="vertical"
274	        aria-label="Resize sidebar"
275	        aria-valuemin={SIDEBAR.RAIL}
276	        aria-valuemax={SIDEBAR.MAX}
277	        aria-valuenow={compact ? SIDEBAR.RAIL : width}
278	        aria-valuetext={compact ? "Compact" : `${width} pixels`}
279	        data-testid="sidebar-resize"
280	        onPointerDown={onPointerDown}
281	        onPointerMove={onPointerMove}
282	        onPointerUp={endDrag}
283	        onPointerCancel={endDrag}
284	        onLostPointerCapture={endDrag}
285	        onDoubleClick={toggle}
286	        onKeyDown={onKeyDown}
287	        className="group absolute inset-y-0 -end-1.5 z-30 w-3 cursor-col-resize touch-none outline-none"
288	      >
289	        <span
290	          aria-hidden="true"
291	          className={`absolute inset-y-0 start-1/2 w-0.5 -translate-x-1/2 transition-colors duration-(--motion-fast) ease-(--ease-standard) group-hover:bg-ring/45 group-focus-visible:bg-ring ${
292	            dragging ? "bg-ring/70" : "bg-transparent"
293	          }`}
294	        />
295	      </div>
296	    </m.aside>
297	  );
298	}
