  1	import { useCallback, useEffect, useState } from "react";
  2	import { handleUnauthorized } from "@/lib/auth";
  3	import { DEFAULT_CAPS, type TurnCaps } from "@/lib/turn-usage";
  4	
  5	type CapsResponse = TurnCaps & { defaults: TurnCaps };
  6	
  7	export type AgentCaps = {
  8	  /** The user's caps for this agent; null until loaded (callers fall back to the defaults). */
  9	  caps: TurnCaps | null;
 10	  defaults: TurnCaps;
 11	  /** PUT the caps; resolves to an error message, or null on success. */
 12	  save: (caps: TurnCaps) => Promise<string | null>;
 13	  /** DELETE: back to the defaults; resolves to an error message, or null on success. */
 14	  reset: () => Promise<string | null>;
 15	};
 16	
 17	function isCapsResponse(value: unknown): value is CapsResponse {
 18	  const body = value as Partial<CapsResponse> | null;
 19	  return (
 20	    !!body &&
 21	    typeof body.costCapUsd === "number" &&
 22	    typeof body.tokenCap === "number" &&
 23	    typeof body.defaults?.costCapUsd === "number" &&
 24	    typeof body.defaults?.tokenCap === "number"
 25	  );
 26	}
 27	
 28	/** The signed-in user's per-turn caps for one agent (GET/PUT/DELETE /api/agents/:agentKey/caps). */
 29	export function useAgentCaps(agentKey: string): AgentCaps {
 30	  const [state, setState] = useState<{ caps: TurnCaps | null; defaults: TurnCaps }>({ caps: null, defaults: DEFAULT_CAPS });
 31	  const url = `/api/agents/${encodeURIComponent(agentKey)}/caps`;
 32	
 33	  const request = useCallback(
 34	    async (init?: RequestInit): Promise<string | null> => {
 35	      try {
 36	        const res = await fetch(url, init);
 37	        if (res.status === 401) {
 38	          handleUnauthorized();
 39	          return "Your session has ended. Sign in again.";
 40	        }
 41	        const body: unknown = await res.json().catch(() => null);
 42	        if (!res.ok) {
 43	          const error = (body as { error?: unknown } | null)?.error;
 44	          return typeof error === "string" ? error : `Request failed (${res.status}).`;
 45	        }
 46	        if (!isCapsResponse(body)) return "Unexpected response from the server.";
 47	        setState({ caps: { costCapUsd: body.costCapUsd, tokenCap: body.tokenCap }, defaults: body.defaults });
 48	        return null;
 49	      } catch {
 50	        return "Can't reach the server.";
 51	      }
 52	    },
 53	    [url],
 54	  );
 55	
 56	  useEffect(() => {
 57	    setState({ caps: null, defaults: DEFAULT_CAPS });
 58	    void request();
 59	  }, [request]);
 60	
 61	  return {
 62	    ...state,
 63	    save: (caps) =>
 64	      request({ method: "PUT", headers: { "content-type": "application/json" }, body: JSON.stringify(caps) }),
 65	    reset: () => request({ method: "DELETE" }),
 66	  };
 67	}
