13	// Open the database and create the table idempotently; safe to call repeatedly.
14	function ownersDb(): Database.Database {
15	  if (db) return db;
16	  const conn = new Database(resolve(dataDir(), "auth.db"));
17	  conn.pragma("busy_timeout = 5000");
18	  conn.exec(`
19	    CREATE TABLE IF NOT EXISTS trace_owner (
20	      trace_id TEXT PRIMARY KEY,
21	      user_id TEXT NOT NULL,
22	      created_at INTEGER NOT NULL
23	    );
24	  `);
25	  db = conn;
26	  return conn;
27	}
