34	/** Records the user as owner of each trace id it has no owner for yet (first owner wins). */
35	export function recordTraceOwners(userId: string, traceIds: Iterable<string>): void {
36	  const conn = ownersDb();
37	  const insert = conn.prepare("INSERT OR IGNORE INTO trace_owner (trace_id, user_id, created_at) VALUES (?, ?, ?)");
38	  const now = Date.now();
39	  conn.transaction(() => {
40	    for (const traceId of traceIds) {
41	      const id = normalize(traceId);
42	      if (id) insert.run(id, userId, now);
43	    }
44	  })();
