312	/**
313	 * Server-side lookup of one trace's cost and tokens through the shared (project-level) Neatlogs MCP
314	 * client. Never exposed to an agent: callers must pass only a trace id the server itself created
315	 * for the requesting user. Asks for a single span and no evaluations, since only the trace totals
316	 * are read (span payloads are ignored; Neatlogs rejects `fields` projection for now). Resolves to
317	 * null when the trace is not (yet) known to Neatlogs, the key is missing, or the result can't be read.
318	 */
319	export async function getTraceMetrics(traceId: string): Promise<TraceMetrics | null> {
320	  const tool = (await getAllNeatlogsTools())[`${TOOL_KEY_PREFIX}get_trace_context`];
321	  if (!tool?.execute) return null;
322	  let raw: unknown;
323	  try {
324	    raw = await tool.execute(
325	      { trace_id: traceId, include_evaluations: false, limit: 1 } as never,
326	      {} as ExecuteContext,
327	    );
328	  } catch {
329	    return null; // "Trace not found" (not ingested yet) is reported as a thrown tool error.
330	  }
331	  const parsed = parseResult(raw);
332	  if (!isRecord(parsed) || typeof parsed.trace_id !== "string" || parsed.trace_id.toLowerCase() !== traceId.toLowerCase()) {
333	    return null;
334	  }
335	  const inputTokens = finite(parsed.prompt_tokens);
336	  const outputTokens = finite(parsed.completion_tokens);
337	  return {
338	    finalized: parsed.finalization_status === "finalized",
339	    costUsd: finite(parsed.total_cost),
340	    tokens: finite(parsed.total_tokens) || inputTokens + outputTokens,
341	    inputTokens,
342	    outputTokens,
343	  };
344	}
